{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "“Given the health and economic threats posed by the pandemic to the global community, there are concerns that rates of suicide and suicidal behaviour may rise during and in its aftermath.”\n\n“…there is thus far no clear evidence of an increase in suicide, self-harm, suicidal behaviour, or suicidal thoughts associated with the pandemic. However, suicide data are challenging to collect in real time and economic effects are evolving.”",
      "reason": "Describes existing concerns and indicates an important uncertainty (“thus far no clear evidence…”) and some limitations/challenges (“suicide data are challenging to collect in real time”). However, it does not clearly describe the broader current state of knowledge and uncertainties in a comprehensive way beyond this framing."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "“Our living systematic review (LSR) focuses on suicide prevention in relation to COVID-19… Our LSR will provide a regular synthesis of the most up-to-date research evidence to guide public health and clinical policy to mitigate the impact of COVID-19 on suicide.”",
      "reason": "Explains why the review is needed by stating it will synthesize up-to-date evidence to guide public health and clinical policy."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was provided that the manuscript explains the need for the review in light of similar systematic reviews, including updates/replications and citations of previous reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The conditional requirement refers to reviews of intervention effects and the mechanism of action of an intervention. The retrieved evidence describes a living systematic review focused on evidence related to COVID-19 exposure/outcomes and synthesis, but does not provide intervention mechanism information indicating an intervention-effect review."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The conditional requirement is for complex interventions or delivery contexts and would require a logic model. The retrieved evidence does not indicate a logic model is used or needed for the review’s scope based on the provided excerpts."
    }
  ],
  "confidence": 72
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The overarching aim of the review is to identify and appraise any newly published evidence from around the world that assesses the impact of the COVID-19 pandemic on suicide deaths, suicidal behaviours, self-harm and suicidal thoughts, or that assesses the effectiveness of strategies to reduce the risk of suicide deaths, suicidal behaviours, self-harm and suicidal thoughts, resulting from the COVID-19 pandemic.",
      "reason": "The review’s overall aim is explicitly stated, but the evidence provided does not show that the objectives/questions are explicitly formulated using a specific relevant question-formulation framework (beyond describing outcomes/assessments)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was provided stating planned comparisons for intervention effects (e.g., PICO or appropriate variant)."
    }
  ],
  "confidence": 62
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Study participants may be adults or children of any ethnicities living in any country. Outcomes of interest are: \u0007 Deaths by suicide \u0007 Self-harm (intentional self-injury or self-poisoning regardless of motivation and intent) or attempted suicide (including hospital attendance and/or admission for these reasons) \u0007 Suicidal thoughts/ideation Figure 1. Workflow for updating the living systematic review review. The process will be supported using automation technology and at three-monthly intervals the team will update the published version of the review.",
      "reason": "The evidence specifies participant characteristics and the outcomes of interest, but it does not fully specify all study-characteristic components needed for eligibility (e.g., eligible study designs, settings, and follow-up requirements) in a complete, checklist-like way."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Eligibility criteria include incidence/prevalence of suicidal behaviour, exposure-outcome relationships and effects of interventions in relation to the COVID-19 pandemic. Outcomes of interest are suicide, self-harm or attempted suicide and suicidal thoughts. No restrictions are placed on language or study type, except for single-person case reports.",
      "reason": "The evidence states there are no language restrictions and an exception for single-person case reports, but it does not clearly specify eligibility criteria for report characteristics such as dissemination year and publication/report status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was retrieved that distinguishes exclusions where outcomes were not measured versus exclusions where outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_20",
      "quote": "We synthesised studies according to themes based on research questions and study design, using tables and narrative. Results were synthesised separately for studies in the general population, in health and social care staff and other at-risk occupations, and in vulnerable populations (e.g. people of older age or those with underlying conditions that predispose them to becoming severely ill or dying after contracting COVID-19).",
      "reason": "The evidence specifies groups used for synthesis (general population; health/social care staff/other at-risk occupations; vulnerable populations) and indicates they are based on research questions and study design, but it does not explicitly link these groups to specific comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although a notable restriction is mentioned (exclusion of single-person case reports), no rationale for this or other eligibility restrictions is provided in the retrieved evidence."
    }
  ],
  "confidence": 62
}

